from checks import available
def reserve(stock, requests):
    requests = [(sku, sum(q for _, q in requests if _ == sku)) for sku, q in requests]
    new_stock = stock.copy()
    for sku, quantity in requests:
        if quantity <= 0: raise ValueError('nonpositive quantity')
        if not available(new_stock, sku, quantity): raise ValueError('unavailable')
        new_stock[sku] -= quantity
    return new_stock

